import java.util.ArrayList;
import java.util.List;

public class Main {
    static void printAll(List<?> box) {
        for (Object x : box) {
            System.out.println(x);
        }
    }

    public static void main(String[] args) {
        List<String> names = new ArrayList<>();
        names.add("{w1}");
        names.add("{w2}");
        printAll(names);
    }
}
